records.bodyExcerpt:
function contractURIForCollection(address core, uint256 collectionId)
        external
        view
        returns (string memory);

function mint(
        address[] memory _recipients,
        string[] memory _tokenData,
        uint256[] memory _saltfun_o,
        uint256 _collectionID,
        uint256[] memory _numberOfTokens
    ) external returns (uint256);

function mintAndAuction(
        address _recipient,
        string memory _tokenData,
        uint256 _saltfun_o,
        uint256 _collectionID,
        uint256 _auctionEndTime
    ) external returns (uint256);

function registeredPhasePolicyHash(address manager, uint256 collectionId, bytes32 phaseId)
        external
        view
        returns (bytes32);

function deriveCounterValueKey(
        address manager,
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 counterId,
        bytes32 subjectKey
    ) external pure returns (bytes32);

function consume(
        uint256 collectionId,
        bytes32 phaseId,
        CounterConsumption[] calldata consumptions,
        bytes32 authorizationId,
        bytes32[] calldata nullifiers,
        bytes32 boundPolicyHash,
        bytes32 operationRoot
    ) external;

function isManagerAuthorizationUsed(address manager, bytes32 authorizationId)
        external
        view
        returns (bool);

function registeredCounterPolicy(
        address manager,
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 counterId
    ) external view returns (LedgerCounterPolicy memory);

function policyGrace(address manager, uint256 collectionId, bytes32 phaseId)
        external
        view
        returns (
            bytes32 previousPolicyHash,
            uint64 previousPolicyRevision,
            uint64 previousPolicyGraceUntil
        );

function registerPhasePolicy(
        address manager,
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 policyHash,
        bytes32[] calldata counterIds,
        LedgerCounterPolicy[] calldata counterPolicies,
        uint64 graceUntil
    ) external;

function isManagerOperationRootUsed(address manager, bytes32 operationRoot)
        external
        view
        returns (bool);

function configurePhase(
        uint256 collectionId,
        bytes32 phaseId,
        MintPhaseConfig calldata config,
        MintGateConfig calldata gateConfig,
        bytes32[] calldata counterIds,
        MintCounterConfig[] calldata counterConfigs
    ) external returns (bytes32 policyHash);

function phase(uint256 collectionId, bytes32 phaseId)
        external
        view
        returns (bool exists, MintPhaseConfig memory config);

function phasePolicyGrace(uint256 collectionId, bytes32 phaseId)
        external
        view
        returns (bytes32 previousPolicyHash, uint64 graceUntil);

function executeSingleStepMint(MintBatch calldata batch, bytes calldata gateData)
        external
        returns (uint256[] memory tokenIds, bytes32 operationRoot, bytes32[] memory operationIds);

function counterConfig(uint256 collectionId, bytes32 phaseId, bytes32 counterId)
        external
        view
        returns (MintCounterConfig memory);

function previewCounterValueKey(
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 counterId,
        bytes32 subjectKey
    ) external view returns (bytes32);

function phaseCounterIds(uint256 collectionId, bytes32 phaseId)
        external
        view
        returns (bytes32[] memory);

function phaseGate(uint256 collectionId, bytes32 phaseId)
        external
        view
        returns (MintGateConfig memory);

function phaseExecutor(uint256 collectionId, bytes32 phaseId, address executor)
        external
        view
        returns (bool);

function previewSingleStepMintOperation(MintBatch calldata batch, bytes calldata gateData)
        external
        view
        returns (bytes32 operationRoot, bytes32[] memory operationIds);

function executePreparedMint(MintBatch calldata batch, bytes calldata gateData)
        external
        returns (uint256[] memory tokenIds, bytes32 operationRoot, bytes32[] memory operationIds);
